const fs = await import('node:fs');
const path = globalThis.inputPath;
if (!fs.existsSync(path)) {
  throw new Error('Input file not found: ' + path);
}
const buffer = fs.readFileSync(path);
globalThis.noteBuffer = buffer;

const mod = await import('supernote-typescript');
const { SupernoteX, toPdf } = mod;
const note = new SupernoteX(globalThis.noteBuffer);
const pdfBytes = await toPdf(note);
globalThis.pdfBytes = pdfBytes;

const fs = await import('node:fs');
const outputPath = globalThis.inputPath.replace(/\.note$/, '.pdf');
fs.writeFileSync(outputPath, globalThis.pdfBytes);
console.log(JSON.stringify({ pdf_path: outputPath }));
